import{_ as a,o as t,c as i,a3 as d}from"./chunks/framework.B8xISX-C.js";const u=JSON.parse('{"title":"Overview","description":"","frontmatter":{"title":"Overview"},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),r={name:"index.md"};function o(n,e,s,l,h,c){return t(),i("div",null,[...e[0]||(e[0]=[d('<h1 id="modding-throne-of-carina" tabindex="-1">Modding Throne of Carina <a class="header-anchor" href="#modding-throne-of-carina" aria-label="Permalink to &quot;Modding Throne of Carina&quot;">​</a></h1><p>Throne of Carina is a turn-based space strategy game that runs in the browser (<a href="https://jkir.itch.io/carina" target="_blank" rel="noreferrer">play it on itch.io</a>). This site is the modding guide, the generated reference, a set of example mods and a page that checks a mod.</p><p>Making a mod takes no programming. You edit JSON files, add pictures and sound, and run one command-line tool.</p><h2 id="what-a-mod-is" tabindex="-1">What a mod is <a class="header-anchor" href="#what-a-mod-is" aria-label="Permalink to &quot;What a mod is&quot;">​</a></h2><p>A mod is a folder, or a <code>.carinamod</code> file, which is that folder zipped. It holds data only: JSON records and rule changes, text, pictures and sound. No code runs from a mod. The game checks every mod when you import it and says what is wrong and where.</p><h2 id="where-to-start" tabindex="-1">Where to start <a class="header-anchor" href="#where-to-start" aria-label="Permalink to &quot;Where to start&quot;">​</a></h2><ul><li><a href="/carina-mod-template/guide/first-mod">Your first mod</a>: make, check, pack and play a small mod.</li><li><a href="/carina-mod-template/examples/">Example mods</a>: working mods to read, download and copy.</li><li><a href="/carina-mod-template/check">Check my mod</a>: the game&#39;s importer in this page, without installing anything.</li></ul><h2 id="what-a-mod-can-add" tabindex="-1">What a mod can add <a class="header-anchor" href="#what-a-mod-can-add" aria-label="Permalink to &quot;What a mod can add&quot;">​</a></h2><ul><li>Research fields, spliced into one of the eight research areas, with up to four applications each.</li><li>Beam weapons in full. Missiles, torpedoes, fighters and special weapons, with their combat-rules rows and an existing special kind.</li><li>Armour, shields and computers.</li><li>Ship specials. A new special adds no new behaviour.</li><li>Buildings, made from the closed list of effect kinds and the existing autobuild formulas.</li><li>Races and special race picks.</li><li>Text keys.</li><li>Pictures and sound for any base role, and pictures for new races and buildings.</li></ul><h2 id="what-a-mod-can-change" tabindex="-1">What a mod can change <a class="header-anchor" href="#what-a-mod-can-change" aria-label="Permalink to &quot;What a mod can change&quot;">​</a></h2><ul><li>Any value of any base record, by patch rows. This includes the closed catalogs (<a href="/carina-mod-template/reference/rules">Rules catalogs</a>): hulls, drives, fuel cells, governments, combat rules and the computer players&#39; tables. A value stays within its field&#39;s range, and a fixed table keeps its length.</li><li>Base records of the open catalogs can be removed.</li><li>The starting technology of each start level.</li><li>Technology that only a pick or a race can research.</li><li>Base text, except proper names. <a href="/carina-mod-template/reference/text">Base text</a> lists the keys.</li></ul><h2 id="what-needs-a-game-update" tabindex="-1">What needs a game update <a class="header-anchor" href="#what-needs-a-game-update" aria-label="Permalink to &quot;What needs a game update&quot;">​</a></h2><ul><li>New hulls, governments, drives and fuel cells. These catalogs are closed.</li><li>New effect kinds, special weapon kinds, weapon classes, weapon mods, autobuild formulas and trait levels.</li><li>A ninth research area, or a fifth application in a field.</li><li>New random events. The events catalog is closed.</li><li>Scenarios, campaigns, interface changes and scripts. The folders <code>rules/</code>, <code>scenarios/</code>, <code>campaigns/</code>, <code>ui/</code> and <code>scripts/</code> are refused with <code>needs-newer-game</code>.</li><li>Text in languages other than English. It is reported as <code>text-locale-unused</code> and not used.</li><li>A weapon cost that depends on the empire.</li><li>Quick-rebuild of a mod&#39;s buildings by Hard and Impossible computer players.</li></ul><p><a href="/carina-mod-template/reference/limits">Limits</a> lists every bound.</p><h2 id="multiplayer" tabindex="-1">Multiplayer <a class="header-anchor" href="#multiplayer" aria-label="Permalink to &quot;Multiplayer&quot;">​</a></h2><p>In multiplayer every player needs the same rule mods. The game compares them by hash, not by name. A player who joins a game with mods they lack, or have in another version, sees which ones differ. The game never sends mods between players. GET FROM CATALOG installs the differing mods from the <a href="/carina-mod-template/guide/sharing">mod catalog</a> when it lists them.</p><p>Every player holds the full rules of the game, so a mod cannot keep a rule secret. Pictures, sound and text may differ between players.</p><h2 id="the-guide" tabindex="-1">The guide <a class="header-anchor" href="#the-guide" aria-label="Permalink to &quot;The guide&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>What it covers</th></tr></thead><tbody><tr><td><a href="/carina-mod-template/guide/first-mod">Your first mod</a></td><td>A walkthrough from the template to a mod in the game.</td></tr><tr><td><a href="/carina-mod-template/guide/copying-an-example">Copying an example</a></td><td>What to change when an example mod is your starting point.</td></tr><tr><td><a href="/carina-mod-template/guide/rules-changes">Rules changes</a></td><td>Patch rows: change a value, a list or a record.</td></tr><tr><td><a href="/carina-mod-template/guide/new-content">New content</a></td><td>Records, text and the layout of a mod folder.</td></tr><tr><td><a href="/carina-mod-template/guide/pictures-and-sound">Pictures and sound</a></td><td>Roles, sizes and formats.</td></tr><tr><td><a href="/carina-mod-template/guide/dependencies">Dependencies and compatibility</a></td><td>Needing, ordering and excluding other mods.</td></tr><tr><td><a href="/carina-mod-template/guide/testing">Testing</a></td><td>Check, run, import and dev mode.</td></tr><tr><td><a href="/carina-mod-template/guide/updates">Releasing an update</a></td><td>Versions, hashes and save migrations.</td></tr><tr><td><a href="/carina-mod-template/guide/sharing">Sharing</a></td><td>Files, the catalog and external pages.</td></tr><tr><td><a href="/carina-mod-template/guide/troubleshooting">Troubleshooting</a></td><td>Common issues and what they mean.</td></tr></tbody></table>',19)])])}const p=a(r,[["render",o]]);export{u as __pageData,p as default};
